{"command": "python3 - <<'EOF'
from PIL import Image, ImageDraw
img = Image.open('radiograph.jpg').convert('RGB')
d = ImageDraw.Draw(img)
# grid every 100 px, labels every 200
for x in range(0, img.width, 100):
    d.line([(x,0),(x,img.height)], fill=(0,120,255), width=1)
for y in range(0, img.height, 100):
    d.line([(0,y),(img.width,y)], fill=(0,120,255), width=1)
for x in range(0, img.width, 200):
    for y in range(0, img.height, 200):
        d.text((x+2,y+2), f"{x},{y}", fill=(255,80,80))
img.save('crops/grid.png')
print('ok')
EOF", "description": "Overlay coordinate grid on radiograph"}

{"command": "python3 - <<'EOF'
from PIL import Image, ImageDraw, ImageOps
img = Image.open('radiograph.jpg').convert('L')
c = img.crop((480, 430, 1100, 850))
c = ImageOps.autocontrast(c, cutoff=1)
c = c.resize((c.width*2, c.height*2), Image.LANCZOS)
rgb = Image.merge('RGB',(c,c,c))
d = ImageDraw.Draw(rgb)
for gx in range(500, 1100, 50):
    d.line([((gx-480)*2,0),((gx-480)*2,rgb.height)], fill=(0,150,255), width=1)
    if gx%100==0: d.text(((gx-480)*2+2,2), str(gx), fill=(255,60,60))
for gy in range(450, 850, 50):
    d.line([(0,(gy-430)*2),(rgb.width,(gy-430)*2)], fill=(0,150,255), width=1)
    if gy%100==0: d.text((2,(gy-430)*2+2), str(gy), fill=(255,60,60))
rgb.save('crops/map_lr.png'); print(rgb.size)
EOF", "description": "Labeled grid map of lower right quadrant"}
